import fs from 'node:fs';
const R = 'C:/MAPWARSJ/剧本模式/';
const DIR = R + '99_GG任务与交付/';
const quota = Object.fromEntries(JSON.parse(fs.readFileSync(R + '02_播报文案/编年史主线1022场_战略播报字数设计表_63章新序_2026-11-16.json', 'utf8')).map((r) => [r.id, r]));
const len = (s) => Array.from(s).length;
// [id, 字段, 原文片段, 新片段, 原因]
const FIX = [
  ['evt_0105', '战略', '奇袭斯巴达造船重镇吉雄军港。', '奇袭斯巴达南疆造船重镇。', '战略结尾「吉雄军港」与战术开头复读'],
  ['evt_0192', '战略', '遂挥师南转合围萨摩斯城。', '遂挥师南转合围这座岛邦。', '战略结尾「萨摩斯城」与战术开头复读'],
  ['evt_0556', '战略', '文提狄乌斯夺山隘迫帕提亚军退回河东，光复叙利亚。', '帕提亚军被逐回幼发拉底河东岸，叙利亚光复。', '战略与战术都以「文提狄乌斯」开头'],
  ['evt_0176', '战略', '奇袭底比斯卫城卡德米亚。', '奇袭底比斯卫城。', '战略结尾「卡德米亚」与战术开头复读（定稿原文）'],
  ['evt_0209', '战略', '猛扑东岸要冲斯塔吉拉。', '猛扑同盟东翼要冲。', '战略结尾「斯塔吉拉」与战术开头复读（定稿原文）'],
  ['evt_0210', '战略', '连破守军合围奥林索斯。', '连破守军合围同盟都城。', '战略结尾「奥林索斯」与战术开头复读（定稿原文）'],
  ['evt_0413', '战略', '兵临乌斯卡纳。', '兵临罗马戍守的山城。', '战略结尾「乌斯卡纳」与战术开头复读（定稿原文）'],
  ['evt_0553', '战略', '困于翁布里亚山城佩鲁西亚。', '困于翁布里亚山城。', '战略结尾「佩鲁西亚」与战术开头复读（定稿原文）'],
  ['evt_0111', '战术', '斯帕尔顿，率领的', '斯帕尔顿率领的', '断句残留'],
  ['evt_0137', '战术', '脱节之，机突入', '脱节之机突入', '断句残留'],
  ['evt_0198', '战术', '久经沙场的，达达尼亚', '久经沙场的达达尼亚', '断句残留'],
  ['evt_0210', '战术', '守方骑兵，统帅拉斯特涅斯', '守方骑兵统帅拉斯特涅斯', '断句残留'],
  ['evt_0394', '战术', '高洛托斯，率领下', '高洛托斯率领下', '断句残留'],
  ['evt_0596', '战术', '梅萨利努斯亦，率偏师', '梅萨利努斯亦率偏师', '断句残留'],
  ['evt_0834', '战术', '申耽，及其弟申仪', '申耽及其弟申仪', '断句残留'],
  ['evt_0882', '战术', '新擢骑兵，统帅奥勒良', '新擢骑兵统帅奥勒良', '断句残留'],
  ['evt_0889', '战术', '伊利里亚重步兵，与铁骑', '伊利里亚重步兵与铁骑', '断句残留'],
  ['evt_1241', '战略', '重重围困于雁门郡城。', '重重围困于代北孤城。', '战略结尾「雁门郡城」与战术开头复读（定稿原文）'],
  ['evt_1343', '战略', '希萨尔山麓险固的舒曼要塞。', '希萨尔山麓的险固山城。', '战略结尾「舒曼要塞」与战术开头复读（定稿原文）'],
  ['evt_1371', '战略', '星夜出击哈里斯坦。', '星夜出击突骑施冬营。', '战略结尾「哈里斯坦」与战术开头复读（定稿原文）'],
  ['evt_1387', '战略', '前锋直抵咽喉坚城菩萨劳城。', '前锋直抵扼守河谷咽喉的坚城。', '战略结尾「菩萨劳城」与战术开头复读（定稿原文）'],
  ['evt_1830', '战略', '神罗皇帝自科莫率精骑南下', '神圣罗马皇帝自科莫南下', '「神罗」是网络简称，改正式称呼'],
  ['evt_1516', '战略', '公元八七八年夏', '公元八七八年春', '埃丁顿之战在878年5月，属春季'],
  ['evt_1794', '战略', '公元一一四〇年夏', '公元一一四〇年秋', '颍昌之战在绍兴十年七月，与前一场郾城同属秋季'],
  ['evt_0993', '战术', '萨弗拉克斯，统领', '萨弗拉克斯统领', '断句残留'],
  ['evt_1240', '战术', '婴阳王急，遣使', '婴阳王急遣使', '断句残留'],
  ['evt_1373', '战术', '夫蒙灵詧，会同', '夫蒙灵詧会同', '断句残留'],
];
const files = fs.readdirSync(DIR).filter((f) => /^GG交付_主线63章战略播报改写_第\d幕/.test(f) && f.endsWith('.json'));
const data = Object.fromEntries(files.map((f) => [f, JSON.parse(fs.readFileSync(DIR + f, 'utf8'))]));
const log = [];
const dirty = new Set();
for (const [id, field, from, to, why] of FIX) {
  const f = files.find((x) => data[x].some((g) => g.id === id));
  const g = data[f].find((x) => x.id === id);
  const q = quota[id];
  if (field === '战略') {
    const i = g.合并战略播报.findIndex((p) => p.includes(from));
    if (i < 0) { if (g.合并战略播报.some((p) => p.includes(to))) { log.push(`| #${g.新序号} | ${id} | ${field} | ${why} | ${from} → ${to} |`); continue; } throw new Error(`${id} 找不到：${from}`); }
    g.合并战略播报[i] = g.合并战略播报[i].replace(from, to);
    const tot = g.合并战略播报.reduce((a, p) => a + len(p), 0);
    if (tot < q.战略最少字 || tot > q.战略最多字 || len(g.合并战略播报[i]) < q.单段最少字 || len(g.合并战略播报[i]) > q.单段最多字) throw new Error(`${id} 改后 ${tot} 字超出 ${q.战略最少字}–${q.战略最多字}`);
  } else {
    if (!g.战术播报.includes(from)) { if (g.战术播报.includes(to)) { log.push(`| #${g.新序号} | ${id} | ${field} | ${why} | ${from} → ${to} |`); continue; } throw new Error(`${id} 找不到：${from}`); }
    g.战术播报 = g.战术播报.replace(from, to);
    const n = len(g.战术播报);
    if (n < 89 || n > 144) throw new Error(`${id} 战术改后 ${n} 字`);
  }
  log.push(`| #${g.新序号} | ${id} | ${field} | ${why} | ${from} → ${to} |`);
  dirty.add(f);
}
// 只写有改动的文件（云盘同步时会锁住刚同步的文件）
for (const f of dirty) fs.writeFileSync(DIR + f, JSON.stringify(data[f], null, 2), 'utf8');
const md = ['# CC 修正记录：主线63章（逐幕累计）（2026-11-16）', '', 'GG 交付已核对通过，以下是 CC 直接修改的地方，GG 后续各幕请注意避免同类问题：', '', '1. **断句残留**：句子中间多出逗号，把一个词组切开（如「久经沙场的，达达尼亚」）。这些都来自 11-15 定稿原文，本次一并修掉。', '2. **战略与战术复读**：战略播报结尾的词和战术播报开头的词相同，或两段都以同一个人名开头，念出来像重复。改写战略播报时请避开战术播报开头的那几个字。', '', '| 新序号 | 事件 | 字段 | 原因 | 修改 |', '|---:|---|---|---|---|', ...log, '', '事件数据季节有误、待导入时改数据（文字不改）：evt_0622 崤底之战应为春（建武三年闰正月）；evt_1793 郾城、evt_1794 颍昌应为秋（绍兴十年七月）；evt_1516 埃丁顿保持春。', '', '第 5 幕 GG 已按本记录主动清理原文：13 处断句逗号、11 处复读换词，核对无误。'];
fs.writeFileSync(DIR + 'CC修正记录_主线63章_2026-11-16.md', md.join('\n') + '\n', 'utf8');
console.log(`改了 ${log.length} 处`);
